function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 50) return 's has 1 to 50 characters.';
  if (!/^[a-z{},]+$/.test(s)) return "s contains only lowercase letters, '{', '}' and ','.";
  const tokens = s.match(/\{[^{}]*\}|[a-z]|./g);
  for (const token of tokens) {
    if (token.length === 1 && !/[a-z]/.test(token)) return 'Braces must be balanced and not nested; commas belong inside braces.';
    if (token.length > 1) {
      if (!/^\{[a-z](,[a-z])*\}$/.test(token)) return 'Inside braces, list single letters separated by commas.';
      const options = token.slice(1, -1).split(',');
      if (new Set(options).size !== options.length) return 'The letters inside one pair of braces must differ.';
    }
  }
  return null;
}

