function expand(s) {
  const groups = [];
  let i = 0;
  while (i < s.length) {
    if (s[i] === '{') {
      const close = s.indexOf('}', i);
      groups.push(s.slice(i + 1, close).split(',').sort());
      i = close + 1;
    } else {
      groups.push([s[i]]);
      i++;
    }
  }

  const words = [];
  const path = [];
  function backtrack(index) {
    if (index === groups.length) {
      words.push(path.join(''));
      return;
    }
    for (const letter of groups[index]) {
      path.push(letter);
      backtrack(index + 1);
      path.pop();
    }
  }

  backtrack(0);
  return words;
}

