function expand(s) {
  const tokens = s.match(/\{[^}]*\}|[a-z]/g);
  let words = [''];
  for (const token of tokens) {
    const options = token.length === 1 ? [token] : token.slice(1, -1).split(',');
    const grown = [];
    for (const word of words) for (const option of options) grown.push(word + option);
    words = grown;
  }
  return words.sort();
}

