function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const group = count => {
    const pool = (size === 'large' ? letters : 'abcde').split('');
    const chosen = [];
    while (chosen.length < count) chosen.push(pool.splice(pick(pool.length), 1)[0]);
    return '{' + chosen.join(',') + '}';
  };
  let s = '';
  let total = 1;
  if (size === 'large') {
    for (let attempt = 0; attempt < 200 && s.length < 50; attempt++) {
      const options = rand() < 0.3 ? 1 : 2 + pick(4);
      const token = options === 1 ? letters[pick(26)] : group(options);
      if (s.length + token.length > 50 || total * options > 1500) continue;
      s += token;
      total *= options;
    }
  } else {
    const count = 1 + pick(5);
    for (let t = 0; t < count; t++) {
      s += rand() < 0.4 ? 'abcde'[pick(5)] : group(2 + pick(3));
    }
  }
  return [s];
}
